declare(strict_types=1);session_start();$base=__DIR__;foreach([$base.'/config/config.php',$base.'/config.php'] as$f){if(is_file($f)){require_once$f;break;}}if(!isset($pdo)||!($pdo instanceof PDO)){exit('PDO no disponible.');}$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM personas WHERE id=?');$q->execute([$id]);$p=$q->fetch(PDO::FETCH_ASSOC);if(!$p){http_response_code(404);exit('Expediente no encontrado.');}$q=$pdo->prepare('SELECT * FROM persona_timeline WHERE persona_id=? ORDER BY fecha_evento DESC,id DESC LIMIT 300');$q->execute([$id]);$tl=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT aa.*,a.titulo,a.fecha_inicio FROM actividad_asistencias aa JOIN actividades a ON a.id=aa.actividad_id WHERE aa.persona_id=? ORDER BY a.fecha_inicio DESC");$q->execute([$id]);$acts=$q->fetchAll(PDO::FETCH_ASSOC);$links=[];try{$q=$pdo->prepare('SELECT * FROM persona_vinculacion_actual WHERE persona_id=?');$q->execute([$id]);$links=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable$e){}$c=$p['clasificacion_actual']?:$p['clasificacion_general'];?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($p['nombre_completo'])?></title><style>:root{--o:#f28c18;--n:#111b2f;--bg:#f3f5f9;--mut:#6d7687}*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial;background:var(--bg);color:#172033}.top{background:var(--n);color:#fff;padding:22px}.wrap{max-width:1100px;margin:auto;padding:20px}.hero{background:#fff;border-radius:24px;padding:24px;margin-top:-42px;box-shadow:0 15px 40px #10203a18}.pill{display:inline-block;padding:7px 12px;border-radius:999px;font-size:12px;font-weight:900;background:<?=$c==='ACTIVISTA'?'#fff0dc':'#e7f2ff'?>;color:<?=$c==='ACTIVISTA'?'#9c5800':'#175a98'?>}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.card{background:#fff;border-radius:20px;padding:20px;box-shadow:0 12px 32px #13213a0c}.facts{display:grid;grid-template-columns:1fr 1fr;gap:12px}.fact{background:#f7f8fb;border-radius:14px;padding:12px}.fact small{color:var(--mut);display:block}.timeline{position:relative;padding-left:22px}.event{position:relative;padding:0 0 20px 18px;border-left:2px solid #e4e8ef}.event:before{content:'';position:absolute;left:-7px;top:3px;width:12px;height:12px;border-radius:50%;background:var(--o)}.event h4{margin:0 0 5px}.event small{color:var(--mut)}a{color:var(--o);font-weight:800;text-decoration:none}@media(max-width:720px){.grid{grid-template-columns:1fr}.facts{grid-template-columns:1fr}.wrap{padding:14px}.hero{margin-top:-20px}.top{padding:18px 14px}}</style></head><body><div class="top"><div class="wrap"><a href="expediente360.php">← Volver al dashboard</a></div></div><main class="wrap"><section class="hero"><span class="pill"><?=htmlspecialchars($c?:'SIMPATIZANTE')?></span><h1><?=htmlspecialchars($p['nombre_completo']?:'SIN NOMBRE')?></h1><p>C.I. <?=htmlspecialchars($p['cedula_normalizada'])?> · <?=htmlspecialchars($p['telefono_principal']?:'Sin teléfono')?></p><div class="facts"><div class="fact"><small>Territorio electoral</small><b><?=htmlspecialchars(trim(($p['estado']??'').' · '.($p['municipio']??'').' · '.($p['parroquia']??''),' ·'))?></b></div><div class="fact"><small>Centro de votación</small><b><?=htmlspecialchars($p['centro']?:'No disponible')?></b></div><div class="fact"><small>REP</small><b><?=$p['rep_encontrado']?'Encontrado':'No encontrado'?></b></div><div class="fact"><small>Última actividad</small><b><?=htmlspecialchars($p['ultima_actividad_at']?:'Sin actividad')?></b></div></div></section><div class="grid"><section class="card"><h2>Vinculación actual</h2><?php if($links):foreach($links as$l):?><div class="fact"><small><?=htmlspecialchars($l['tipo_instancia'])?></small><b><?=htmlspecialchars($l['cargo']?:'Sin cargo')?></b><div><?=htmlspecialchars(trim(($l['estado']??'').' · '.($l['municipio']??'').' · '.($l['parroquia']??''),' ·'))?></div></div><?php endforeach;else:?><p>No posee vinculación organizativa activa. Su clasificación actual es simpatizante.</p><?php endif;?><h2>Actividades</h2><?php foreach($acts as$a):?><div class="fact" style="margin-bottom:10px"><small><?=htmlspecialchars($a['fecha_inicio'])?></small><b><?=htmlspecialchars($a['titulo'])?></b><div><?=htmlspecialchars($a['clasificacion_al_registro']?:$a['clasificacion_asistente'])?></div></div><?php endforeach;?><?php if(!$acts):?><p>Sin actividades registradas.</p><?php endif;?></section><section class="card"><h2>Trazabilidad</h2><div class="timeline"><?php foreach($tl as$e):?><div class="event"><h4><?=htmlspecialchars($e['titulo']?:$e['tipo_evento'])?></h4><div><?=htmlspecialchars($e['descripcion']?:'')?></div><small><?=htmlspecialchars($e['fecha_evento'])?> · <?=htmlspecialchars($e['modulo']?:'SISTEMA')?></small></div><?php endforeach;?><?php if(!$tl):?><p>Sin eventos registrados.</p><?php endif;?></div></section></div></main></body></html>